import{_ as l,a0 as o,w as d,s as h,I as e,x as a,a1 as i,A as t,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"通过 SSH 在远程 Linux 系统上执行命令 | LCTT x X-CMD","titleTemplate":false,"description":"通过 SSH 在远程 Linux 系统上执行命令 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通过 SSH 在远程 Linux 系统上执行命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过 SSH 在远程 Linux 系统上执行命令 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20220929 Execute Commands On Remote Linux Systems Via SSH","title":"通过 SSH 在远程 Linux 系统上执行命令","tag":"202211","desc":""},"relativePath":"202211/20220929 Execute Commands On Remote Linux Systems Via SSH.md","filePath":"[post].md"}'),r={name:"202211/20220929 Execute Commands On Remote Linux Systems Via SSH.md"};function c(u,s,g,k,b,m){const n=o("Link");return d(),h("div",null,[s[29]||(s[29]=e("h1",{id:"通过-ssh-在远程-linux-系统上执行命令",tabindex:"-1"},[a("通过 SSH 在远程 Linux 系统上执行命令 "),e("a",{class:"header-anchor",href:"#通过-ssh-在远程-linux-系统上执行命令","aria-label":"Permalink to “通过 SSH 在远程 Linux 系统上执行命令”"},"​")],-1)),s[30]||(s[30]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202211/17/163910g9u42ssfcuk9c290.jpg",alt:""})],-1)),s[31]||(s[31]=e("blockquote",null,[e("p",null,"通过安全的网络连接在远程计算机上调用命令或程序。")],-1)),e("p",null,[s[1]||(s[1]=a("有一天，我正在测试如何在 ",-1)),i(n,{href:"https://ostechnix.com/how-to-keep-ownership-and-file-permissions-intact-when-copying-files-or-directories/"},{default:t(()=>[...s[0]||(s[0]=[a("将文件或目录复制到多个位置和系统时保持完整的文件权限",-1)])]),_:1}),s[2]||(s[2]=a("。当我想检查远程系统上的文件权限时，我必须通过 SSH 登录它并检查属性。从远程系统多次登录和注销的过程让我有点烦，我想，如果我可以",-1)),s[3]||(s[3]=e("strong",null,"在远程 Linux 系统上通过 SSH 执行命令",-1)),s[4]||(s[4]=a("就好了。",-1))]),s[32]||(s[32]=p('<p>幸运的是，在浏览了 <code>ssh</code> 命令的手册页后，我找到了一个解决办法。</p><p>如果你想知道如何本地运行远程系统上运行命令或脚本，而不登录到远程系统，下面的内容会告诉你如何做。</p><h3 id="_1、通过-ssh-在远程-linux-系统上执行命令" tabindex="-1">1、通过 SSH 在远程 Linux 系统上执行命令 <a class="header-anchor" href="#_1、通过-ssh-在远程-linux-系统上执行命令" aria-label="Permalink to “1、通过 SSH 在远程 Linux 系统上执行命令”">​</a></h3><p>从本地系统通过 SSH 在远程系统上运行命令或脚本的典型方法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh &lt;username@IP_Address-or-Doman_name&gt; &lt;Command-or-Script&gt;</span></span></code></pre></div><p>允许我给你们举几个例子：</p><h4 id="_1-1、通过-ssh-在远程系统上运行单个命令" tabindex="-1">1.1、通过 SSH 在远程系统上运行单个命令 <a class="header-anchor" href="#_1-1、通过-ssh-在远程系统上运行单个命令" aria-label="Permalink to “1.1、通过 SSH 在远程系统上运行单个命令”">​</a></h4>',7)),e("p",null,[s[6]||(s[6]=a("假设你想要 ",-1)),i(n,{href:"https://ostechnix.com/find-out-the-linux-distribution-name-version-and-kernel-details/"},{default:t(()=>[...s[5]||(s[5]=[a("查找远程 Linux 系统的内核详细信息",-1)])]),_:1}),s[7]||(s[7]=a("。为此，只需运行：",-1))]),s[33]||(s[33]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 uname -a</span></span></code></pre></div><p>这里，</p><ul><li><code>sk</code> 是远程系统的用户名，</li><li><code>192.168.225.22</code> 是远程系统的 IP 地址，</li><li><code>uname -a</code> 是我想在远程系统上运行的命令。</li></ul><p>示例输出：</p><p><img src="https://ostechnix.com/wp-content/uploads/2019/12/Execute-Commands-On-Remote-Linux-Systems-Via-SSH.gif" alt="通过 SSH 在远程 Linux 系统上执行命令"></p><p>看到没？我并没有实际登录到远程系统，但通过 SSH 在远程系统上执行了 <code>uname</code> 命令，并在本地系统的终端上显示了输出。</p><p>你还可以像下面这样用引号指定命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 &quot;uname -a&quot;</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 &#39;uname -a&#39;</span></span></code></pre></div>',10)),e("p",null,[s[9]||(s[9]=a("如果你已经 ",-1)),i(n,{href:"https://ostechnix.com/how-to-change-apache-ftp-and-ssh-default-port-to-a-custom-port-part-3/"},{default:t(()=>[...s[8]||(s[8]=[a("更改了 SSH 协议的默认端口",-1)])]),_:1}),s[10]||(s[10]=a("，只需使用 ",-1)),s[11]||(s[11]=e("code",null,"-p",-1)),s[12]||(s[12]=a(" 参数指定它。",-1))]),s[34]||(s[34]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -p 2200 sk@192.168.225.22 uname -a</span></span></code></pre></div><h4 id="_1-2、通过-ssh-在远程主机上执行多个命令" tabindex="-1">1.2、通过 SSH 在远程主机上执行多个命令 <a class="header-anchor" href="#_1-2、通过-ssh-在远程主机上执行多个命令" aria-label="Permalink to “1.2、通过 SSH 在远程主机上执行多个命令”">​</a></h4><p>你还可以在远程主机上运行多个命令，方法是将它们放在引号中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 &quot;uname -r &amp;&amp; lsb_release -a&quot;</span></span></code></pre></div><p>或者：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 &quot;uname -r ; lsb_release -a&quot;</span></span></code></pre></div><p>上面的命令将显示我的 Ubuntu 服务器的内核版本和发行版详细信息。</p><p>示例输出：</p><p><img src="https://ostechnix.com/wp-content/uploads/2019/12/Run-multiple-commands-on-remote-systems-via-SSH-on-Linux.png" alt="在 Linux 上通过 SSH 在远程主机上运行多个命令"></p><p>正如一位读者在下面的评论部分提到的那样，你应该用引号指定多个命令。如果不使用引号，第一个命令将在远程系统上执行，第二个命令将仅在本地计算机上执行。整个带引号的命令将按预期在远程计算机上运行。</p><blockquote><p><strong>提示：</strong> 了解 <code>&amp;&amp;</code> 和 <code>;</code> 在命令中的区别：</p><p><code>&amp;&amp;</code> 操作符只有在第一个命令成功时才执行第二个命令。</p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get update &amp;&amp; sudo apt-get upgrade</span></span></code></pre></div><p>在上述示例中，如果第一个命令成功，才会执行 <code>sudo apt-get upgrade</code>。否则，它将不会运行。</p><p><code>;</code> 操作符会执行第二个命令，无论第一个命令是成功还是失败。</p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get update ; sudo apt-get upgrade</span></span></code></pre></div><p>在上述示例中，即使第一个命令失败，<code>sudo apt-get upgrade</code> 也会执行。</p></blockquote><h4 id="_1-3、通过-ssh-在远程机器上调用有-sudo-权限的命令" tabindex="-1">1.3、通过 SSH 在远程机器上调用有 sudo 权限的命令 <a class="header-anchor" href="#_1-3、通过-ssh-在远程机器上调用有-sudo-权限的命令" aria-label="Permalink to “1.3、通过 SSH 在远程机器上调用有 sudo 权限的命令”">​</a></h4><p>有些命令需要 <code>sudo</code> 权限才能运行。例如，以下命令将在我的远程系统上安装 <code>apache2</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 sudo apt install apache2</span></span></code></pre></div><p>示例输出：</p><p><img src="https://ostechnix.com/wp-content/uploads/2019/12/Run-commands-with-sudo-privileges-on-remote-systems-via-SSH.png" alt="通过 SSH 在远程机器上运行有 Sudo 权限的命令"></p><p>注意到了吗？我在上面的命令中使用了 <code>-t</code> 标志，我们需要使用它来强制进行伪终端分配。它用于在远程机器上执行任意基于屏幕的程序，这非常有用。例如，在实现菜单服务时。</p><p>另外，我输入了<strong>两次</strong>密码。第一次是远程用户的密码，以便从本地系统通过 SSH 访问远程系统，第二次是为了向远程用户赋予 sudo 权限，以便安装应用程序（在本例中为 apache2）。</p><p>让我们用以下命令检查 Apache 服务是否正在运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 sudo systemctl status apache2</span></span>
<span class="line"><span>sk@192.168.225.22&#39;s password: </span></span>
<span class="line"><span>[sudo] password for sk: </span></span>
<span class="line"><span>● apache2.service - The Apache HTTP Server</span></span>
<span class="line"><span>Loaded: loaded (/lib/systemd/system/apache2.service; enabled; vendor preset: enabled)</span></span>
<span class="line"><span>Drop-In: /lib/systemd/system/apache2.service.d</span></span>
<span class="line"><span>└─apache2-systemd.conf</span></span>
<span class="line"><span>Active: active (running) since Thu 2019-12-19 11:08:03 UTC; 52s ago</span></span>
<span class="line"><span>Main PID: 5251 (apache2)</span></span>
<span class="line"><span>Tasks: 55 (limit: 2318)</span></span>
<span class="line"><span>CGroup: /system.slice/apache2.service</span></span>
<span class="line"><span>├─5251 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>├─5253 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>└─5254 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Dec 19 11:08:03 ubuntuserver systemd[1]: Starting The Apache HTTP Server...</span></span>
<span class="line"><span>Dec 19 11:08:03 ubuntuserver apachectl[5227]: AH00558: apache2: Could not reliably determine the server&#39;s fully qualified domain name, using 2409:4072:51f:a1b6:a00:27ff:f</span></span>
<span class="line"><span>Dec 19 11:08:03 ubuntuserver systemd[1]: Started The Apache HTTP Server.</span></span></code></pre></div><p>同样的，我们可以通过 SSH 在本地系统上运行远程系统上的任何命令或脚本。</p><h4 id="_1-4、通过-ssh-在远程系统上运行本地脚本" tabindex="-1">1.4、通过 SSH 在远程系统上运行本地脚本 <a class="header-anchor" href="#_1-4、通过-ssh-在远程系统上运行本地脚本" aria-label="Permalink to “1.4、通过 SSH 在远程系统上运行本地脚本”">​</a></h4><p>让我们在本地系统上创建一个简单的脚本来显示关于远程系统的发行版名称、包管理和基本细节等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi system_information.sh</span></span></code></pre></div><p>添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>#Name: Display System Details</span></span>
<span class="line"><span>#Owner: OSTechNIx</span></span>
<span class="line"><span>#----------------------------</span></span>
<span class="line"><span>echo /etc/*_ver* /etc/*-rel*; cat /etc/*_ver* /etc/*-rel*</span></span></code></pre></div><p>按下 <code>ESC</code> 键，输入 <code>:wq</code> 保存退出。</p><p>现在，通过 SSH 命令在远程系统上运行这个脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 &#39;bash -s&#39; &lt; system_information.sh</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk@192.168.225.22&#39;s password: </span></span>
<span class="line"><span>/etc/debian_version /etc/lsb-release /etc/os-release</span></span>
<span class="line"><span>buster/sid</span></span>
<span class="line"><span>DISTRIB_ID=Ubuntu</span></span>
<span class="line"><span>DISTRIB_RELEASE=18.04</span></span>
<span class="line"><span>DISTRIB_CODENAME=bionic</span></span>
<span class="line"><span>DISTRIB_DESCRIPTION=&quot;Ubuntu 18.04.2 LTS&quot;</span></span>
<span class="line"><span>NAME=&quot;Ubuntu&quot;</span></span>
<span class="line"><span>VERSION=&quot;18.04.2 LTS (Bionic Beaver)&quot;</span></span>
<span class="line"><span>ID=ubuntu</span></span>
<span class="line"><span>ID_LIKE=debian</span></span>
<span class="line"><span>PRETTY_NAME=&quot;Ubuntu 18.04.2 LTS&quot;</span></span>
<span class="line"><span>VERSION_ID=&quot;18.04&quot;</span></span>
<span class="line"><span>HOME_URL=&quot;https://www.ubuntu.com/&quot;</span></span>
<span class="line"><span>SUPPORT_URL=&quot;https://help.ubuntu.com/&quot;</span></span>
<span class="line"><span>BUG_REPORT_URL=&quot;https://bugs.launchpad.net/ubuntu/&quot;</span></span>
<span class="line"><span>PRIVACY_POLICY_URL=&quot;https://www.ubuntu.com/legal/terms-and-policies/privacy-policy&quot;</span></span>
<span class="line"><span>VERSION_CODENAME=bionic</span></span>
<span class="line"><span>UBUNTU_CODENAME=bionic</span></span></code></pre></div><p>如果你没有在上面的命令中指定 <code>bash -s</code>，你将获得远程系统的详细信息，但伪终端不会被分配。</p><h4 id="_1-5、将远程主机的命令输出保存到本地主机" tabindex="-1">1.5、将远程主机的命令输出保存到本地主机 <a class="header-anchor" href="#_1-5、将远程主机的命令输出保存到本地主机" aria-label="Permalink to “1.5、将远程主机的命令输出保存到本地主机”">​</a></h4><p>如果你希望与支持团队或同事共享远程系统上运行的命令输出，那么这非常有用。</p><p>以下命令将通过 SSH 在远程系统运行 <code>du -ah</code>，并将输出保存在本地系统的 <code>diskusage.txt</code> 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 du -ah &gt; diskusage.txt</span></span></code></pre></div><p>然后，你可以通过使用 <code>cat</code> 命令或文本编辑器查看 <code>diskusage.txt</code> 文件来分析磁盘使用细节。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat diskusage.txt </span></span>
<span class="line"><span>4.0K ./.profile</span></span>
<span class="line"><span>4.0K ./.gnupg/private-keys-v1.d</span></span>
<span class="line"><span>8.0K ./.gnupg</span></span>
<span class="line"><span>76K ./data/image.jpg</span></span>
<span class="line"><span>128K ./data/file.pdf</span></span>
<span class="line"><span>20K ./data/text.docx</span></span>
<span class="line"><span>5.9M ./data/audio.mp3</span></span>
<span class="line"><span>6.1M ./data</span></span>
<span class="line"><span>0 ./.sudo_as_admin_successful</span></span>
<span class="line"><span>4.0K ./pacman?inline=false</span></span>
<span class="line"><span>4.0K ./.bash_logout</span></span>
<span class="line"><span>4.0K ./.wget-hsts</span></span>
<span class="line"><span>4.0K ./.bash_history</span></span>
<span class="line"><span>0 ./.cache/motd.legal-displayed</span></span>
<span class="line"><span>4.0K ./.cache</span></span>
<span class="line"><span>4.0K ./deb-pacman_1.0-0.deb</span></span>
<span class="line"><span>4.0K ./.bashrc</span></span>
<span class="line"><span>6.2M .</span></span></code></pre></div><h4 id="_1-6、配置-ssh-密钥认证-避免输入密码" tabindex="-1">1.6、配置 SSH 密钥认证，避免输入密码 <a class="header-anchor" href="#_1-6、配置-ssh-密钥认证-避免输入密码" aria-label="Permalink to “1.6、配置 SSH 密钥认证，避免输入密码”">​</a></h4><p>如果你经常在远程系统上运行命令，你可能需要配置基于 SSH 密钥的身份验证，以便每次跳过密码输入。更多细节可以在以下链接中找到。</p>`,40)),e("blockquote",null,[e("p",null,[e("strong",null,[i(n,{href:"https://ostechnix.com/configure-ssh-key-based-authentication-linux/"},{default:t(()=>[...s[13]||(s[13]=[a("Linux 系统下如何配置 SSH 密钥认证",-1)])]),_:1})])])]),s[35]||(s[35]=p('<p>配置了基于 SSH 密钥的认证后，我们可以通过 SSH 在远程机器上执行命令，从而不需要输入密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sk@192.168.225.22 sudo apt update</span></span></code></pre></div><h3 id="_2、通过-sshpass-在远程机器上运行命令" tabindex="-1">2、通过 sshpass 在远程机器上运行命令 <a class="header-anchor" href="#_2、通过-sshpass-在远程机器上运行命令" aria-label="Permalink to “2、通过 sshpass 在远程机器上运行命令”">​</a></h3><p>如果你不想配置基于 SSH 密钥的身份验证，你可以使用 <code>sshpass</code> 实用程序。</p><h4 id="_2-1、什么是-sshpass" tabindex="-1">2.1、什么是 sshpass? <a class="header-anchor" href="#_2-1、什么是-sshpass" aria-label="Permalink to “2.1、什么是 sshpass?”">​</a></h4><p><code>sshpass</code> 是为使用键盘交互密码身份验证模式运行 ssh 而设计的，但它以非交互的方式。简单来说，<code>sshpass</code> 提供了非交互式的方式来验证 SSH 会话。</p><p>SSH 使用直接 TTY 访问来确保密码确实是由交互式键盘用户发出的。<code>sshpass</code> 在一个专用 tty 中运行 SSH，让它误以为从交互用户那里获得了密码。</p><h4 id="_2-2、在-linux-中安装-sshpass" tabindex="-1">2.2、在 Linux 中安装 sshpass <a class="header-anchor" href="#_2-2、在-linux-中安装-sshpass" aria-label="Permalink to “2.2、在 Linux 中安装 sshpass”">​</a></h4><p>在许多 Linux 发行版的默认仓库中都有 <code>sshpass</code> 实用程序。例如，在 Debian、Ubuntu 及其衍生版本中，你可以使用下面的命令来安装 <code>sshpass</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install sshpass</span></span></code></pre></div><h4 id="_2-3、通过-ssh-和-sshpass-在远程机器上执行命令" tabindex="-1">2.3、通过 SSH 和 sshpass 在远程机器上执行命令 <a class="header-anchor" href="#_2-3、通过-ssh-和-sshpass-在远程机器上执行命令" aria-label="Permalink to “2.3、通过 SSH 和 sshpass 在远程机器上执行命令”">​</a></h4><p><code>sshpass</code> 可以通过参数接受密码，或者通过环境变量读取密码，也可以从文本文件中读取密码。</p><p><strong>警告：</strong> 所有这些方法都是 <strong>高度不安全的</strong>。所有系统用户都可以通过 <code>ps</code> 命令看到命令中的密码。<strong>不建议</strong>在生产中使用这些方法。最好使用基于密钥的身份验证。</p><p>让我们看看每种方法的示例。</p><h5 id="将密码作为参数提供" tabindex="-1">将密码作为参数提供 <a class="header-anchor" href="#将密码作为参数提供" aria-label="Permalink to “将密码作为参数提供”">​</a></h5><p>将密码作为参数提供，使用 <code>-p</code> 选项，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sshpass -p &lt;remote-password&gt; ssh remoteuser@ip-address &lt;command-to-execute&gt;</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sshpass -p ubuntu ssh ostechnix@192.168.1.30 uname -a</span></span></code></pre></div><p>其中，</p><ul><li><code>-p ubuntu</code> - 提供远程系统的密码。</li><li><code>ostechnix@192.168.1.30</code> - 远程系统用户名和地址。</li><li><code>uname -a</code> - 要在远程计算机上执行的命令。</li></ul><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux Ubuntu22CT 5.15.60-1-pve #1 SMP PVE 5.15.60-1 (Mon, 19 Sep 2022 17:53:17 +0200) x86_64 x86_64 x86_64 GNU/Linux</span></span></code></pre></div><h5 id="密码作为环境变量提供" tabindex="-1">密码作为环境变量提供 <a class="header-anchor" href="#密码作为环境变量提供" aria-label="Permalink to “密码作为环境变量提供”">​</a></h5><p>在这个方法中，我们声明一个名为 <code>SSHPASS</code> 的环境变量，用远程环境的密码作为其值。然后我们使用 <code>-e</code> 标志，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ SSHPASS=ubuntu sshpass -e ssh ostechnix@192.168.1.30 uname -a</span></span></code></pre></div><h5 id="从文本文件中读取密码" tabindex="-1">从文本文件中读取密码 <a class="header-anchor" href="#从文本文件中读取密码" aria-label="Permalink to “从文本文件中读取密码”">​</a></h5><p>使用 <code>echo</code> 命令在文本文件中追加密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;ubuntu&quot; &gt; mypassword.txt</span></span></code></pre></div><p>现在，将密码文件传递给带有 <code>-f</code> 标志的 <code>sshpass</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sshpass -f mypassword.txt ssh ostechnix@192.168.1.30 uname -a</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/09/Execute-Commands-On-Remote-Machines-Over-SSH-With-sshpass.png" alt="通过 SSH 和 sshpass 在远程机器上执行命令"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在本教程中，我们学习了一些通过安全的网络连接在远程计算机上调用命令或程序的方法。在所有的方法中，<code>sshpass</code> 方法是最不安全的，建议用户避免在生产系统中使用它。</p><hr>',35)),e("p",null,[s[15]||(s[15]=a("via: ",-1)),i(n,{href:"https://ostechnix.com/execute-commands-on-remote-linux-systems-via-ssh/"},{default:t(()=>[...s[14]||(s[14]=[a("https://ostechnix.com/execute-commands-on-remote-linux-systems-via-ssh/",-1)])]),_:1})]),e("p",null,[s[20]||(s[20]=a("作者：",-1)),i(n,{href:"https://ostechnix.com/author/sk/"},{default:t(()=>[...s[16]||(s[16]=[a("sk",-1)])]),_:1}),s[21]||(s[21]=a(" 选题：",-1)),i(n,{href:"https://github.com/lkxed"},{default:t(()=>[...s[17]||(s[17]=[a("lkxed",-1)])]),_:1}),s[22]||(s[22]=a(" 译者：",-1)),i(n,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[18]||(s[18]=[a("MjSeven",-1)])]),_:1}),s[23]||(s[23]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[19]||(s[19]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[26]||(s[26]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[24]||(s[24]=[a("LCTT",-1)])]),_:1}),s[27]||(s[27]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[25]||(s[25]=[a("Linux中国",-1)])]),_:1}),s[28]||(s[28]=a(" 荣誉推出",-1))])])}const y=l(r,[["render",c]]);export{x as __pageData,y as default};
